// Expand each uploaded file into its own item with the binary under a single key 'data'
const results = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    results.push({
      json: { ...item.json, sourceBinaryKey: key, fileName: bin[key].fileName || key },
      binary: { data: bin[key] },
    });
  }
}
return results;

const results = [];
const allAppointments = [];
const allPatients = [];
const allDoctors = [];

// Collect data from all LLM output items.
for (const item of $input.all()) {
  const output = item.json.output || {};
  if (Array.isArray(output.appointments)) allAppointments.push(...output.appointments);
  if (Array.isArray(output.patients)) allPatients.push(...output.patients);
  if (Array.isArray(output.doctors)) allDoctors.push(...output.doctors);
}

// Use a deterministic local clock for validation. This Code node is authoritative;
// it does not rely on the LLM's date_valid assessment.
const nowManila = DateTime.now().setZone('Asia/Manila');

for (const appointment of allAppointments) {
  const patient = allPatients.find(p =>
    String(p.patient_id ?? '').trim() === String(appointment.patient_id ?? '').trim()
  );
  const doctor = allDoctors.find(d =>
    String(d.doctor_id ?? '').trim() === String(appointment.doctor_id ?? '').trim()
  );

  const rawDate = String(appointment.date ?? '').trim();
  const rawTime = String(appointment.time ?? '').trim();

  let dt = DateTime.invalid('Missing or invalid date/time');
  let parseAttempted = false;
  let validationReason = '';

  if (rawDate && rawTime) {
    // Strictly parse only the formats supported by this workflow.
    dt = DateTime.fromFormat(`${rawDate} ${rawTime}`, 'yyyy-M-d h:mm a', {
      zone: 'Asia/Manila',
      locale: 'en-US'
    });
    parseAttempted = true;

    if (!dt.isValid) {
      dt = DateTime.fromFormat(`${rawDate} ${rawTime}`, 'yyyy-M-d H:mm', {
        zone: 'Asia/Manila',
        locale: 'en-US'
      });
    }
  } else {
    validationReason = 'Missing date or time.';
  }

  let dateValid = false;
  let formattedDate = rawDate;
  let formattedTime = rawTime;
  let startIso = null;
  let endIso = null;

  if (!validationReason && (!parseAttempted || !dt.isValid)) {
    validationReason = 'Invalid date/time format or impossible calendar date/time.';
  } else if (!validationReason && dt.isValid && dt.toMillis() <= nowManila.toMillis()) {
    validationReason = 'Appointment date/time is not in the future (Asia/Manila).';
  } else if (!validationReason && dt.isValid) {
    dateValid = true;
    formattedDate = dt.toFormat('MMMM d, yyyy');
    formattedTime = dt.toFormat('h:mm a');
    startIso = dt.toISO();
    endIso = dt.plus({ hours: 1 }).toISO();
  }

  // Keep readable normalized values when parsing succeeded, even if the date/time is past.
  if (dt.isValid) {
    formattedDate = dt.toFormat('MMMM d, yyyy');
    formattedTime = dt.toFormat('h:mm a');
  }

  const doctorName = doctor?.name || 'N/A';
  const specialization = doctor?.specialization || 'N/A';
  const appointmentDetails = `Patient ID: ${appointment.patient_id || 'N/A'}
Doctor: ${doctorName}
Specialization: ${specialization}
Date: ${formattedDate}
Time: ${formattedTime}
Purpose: ${appointment.purpose || 'N/A'}
Status: ${appointment.status || 'N/A'}
Validation: ${dateValid ? 'VALID' : 'INVALID'}${validationReason ? ` - ${validationReason}` : ''}

📍 Clinic: ${appointment.clinic_id || 'N/A'}`;

  results.push({
    json: {
      clinic_id: appointment.clinic_id,
      patient_id: appointment.patient_id,
      doctor_id: appointment.doctor_id,
      date: appointment.date,
      time: appointment.time,
      purpose: appointment.purpose,
      status: appointment.status,
      // Deterministic values override any LLM-provided validation flags.
      date_valid: dateValid,
      date_validation_reason: validationReason,
      patient_name: patient?.name || appointment.patient_id || 'Patient',
      patient_email: patient?.email || '',
      doctor_name: doctorName,
      specialization,
      formatted_date: formattedDate,
      formatted_time: formattedTime,
      start_iso: startIso,
      end_iso: endIso,
      appointment_details: appointmentDetails
    }
  });
}

return results;

