// Match the current RESCHEDULED appointment to an existing Google Calendar event.
const source = $('Collect Appointments').all();
const appointmentData = source.find(item =>
  String(item.json.status ?? '').trim().toUpperCase() === 'RESCHEDULED'
)?.json;

if (!appointmentData) {
  throw new Error('No RESCHEDULED appointment found in Collect Appointments.');
}

const appointmentId = String(appointmentData.clinic_id ?? '').trim();
const patientId = String(appointmentData.patient_id ?? '').trim();
const doctorId = String(appointmentData.doctor_id ?? '').trim();
const purpose = String(appointmentData.purpose ?? '').trim();

const events = $input.all();
const matchingEvent = events.find(item => {
  const event = item.json ?? {};
  const description = String(event.description ?? '');
  const summary = String(event.summary ?? '');

  // Preferred stable match: the appointment ID is saved in the event description.
  if (appointmentId && description.includes(`Appointment ID: ${appointmentId}`)) {
    return true;
  }

  // Fallback for older events created before Appointment ID was saved.
  const patientMatch =
    description.includes(`Patient ID: ${patientId}`) ||
    description.includes(`Appointment Patient ID: ${patientId}`) ||
    description.includes(`Patient: ${patientId}`);
  const doctorMatch =
    description.includes(`Doctor ID: ${doctorId}`) ||
    description.includes(`Doctor: ${doctorId}`);
  const purposeMatch = !purpose || summary.toLowerCase() === purpose.toLowerCase();

  return Boolean(patientId && doctorId && patientMatch && doctorMatch && purposeMatch);
});

if (!matchingEvent) {
  throw new Error(
    `No calendar event found for appointment ${appointmentId}. ` +
    `Patient: ${patientId}, Doctor: ${doctorId}. ` +
    `Older events may need an Appointment ID in their description or a matching Patient ID/Doctor ID.`
  );
}

return [{
  json: {
    eventId: matchingEvent.json.id,
    appointmentId,
    clinic_id: appointmentData.clinic_id,
    patient_id: appointmentData.patient_id,
    patient_name: appointmentData.patient_name,
    patient_email: appointmentData.patient_email,
    doctor_id: appointmentData.doctor_id,
    doctor_name: appointmentData.doctor_name,
    specialization: appointmentData.specialization,
    date: appointmentData.date,
    time: appointmentData.time,
    purpose: appointmentData.purpose,
    status: appointmentData.status,
    start_iso: appointmentData.start_iso,
    end_iso: appointmentData.end_iso
  }
}];

